@Service
public class ProdutoService {
    @Cacheable(value = "produtos", key = "#categoria", sync = true) // evita stampede
    public List<ProdutoResponse> listar(String categoria) {
        return repository.findByCategoria(categoria).stream().map(ProdutoResponse::from).toList();
    }
}

